const M={auto:{id:null},minimax:{id:'minimax/minimax-m3:free'},ultra:{id:'nvidia/nemotron-3-ultra-550b-a55b:free'},super:{id:'nvidia/nemotron-3-super-120b-a12b:free'},lightning:{id:'nvidia/nemotron-3.5-lightning:free'},nano:{id:'nvidia/nemotron-3-nano-omni-30b-a3b-reasoning:free'},ling:{id:'inclusionai/ling-3.0-flash-fin:free'}};
const GQ=['llama-3.3-70b-versatile','openai/gpt-oss-120b','llama-3.1-8b-instant'];
const GQV=['meta-llama/llama-4-scout-17b-16e-instruct','meta-llama/llama-4-maverick-17b-128e-instruct'];
const ORV=['minimax/minimax-m3:free','nvidia/nemotron-3-nano-omni-30b-a3b-reasoning:free'];
const MT=8192,TM=20000;
function pickAuto(m){const u=[...m].reverse().find(x=>x.role==='user');const t=(u?.content||'').toLowerCase();if(t.length>800||/تحقیق|پژوهش|تحلیل|گزارش|معماری|پروژه|research|deep|complex|architecture|project/.test(t))return'ultra';return'ling';}
function sysP(l,c,ca,se){const li=l==='en'?'Respond in English.':l==='ku'?'بە کوردی وەڵام بدەوە.':'به فارسی پاسخ بده.';let ci='';if(c){const a={build:'حالت کدنویسی — ساخت کد. کد کامل و قابل‌اجرا بنویس.',fix:'حالت کدنویسی — رفع باگ. خطا را پیدا کن و راه‌حل بده.',explain:'حالت کدنویسی — توضیح کد. ساده و قابل‌فهم توضیح بده.',optimize:'حالت کدنویسی — بهینه‌سازی. سریع‌تر و بهینه‌تر کن.',project:'حالت کدنویسی — ساخت پروژه. ساختار کامل پروژه.'};ci='\n\n'+(a[ca]||a.build);}const e=se?'\n\n'+se:'';return'تو «هُما» هستی، دستیار هوشمند فارسی. با مارک‌داون خوانا پاسخ بده. کد HTML/CSS/JS را در بلوک ```html بده. '+li+ci+e;}
function ch(){return{'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'POST, OPTIONS','Access-Control-Allow-Headers':'Content-Type, Authorization'};}
function jb(d,s=200){return Response.json(d,{status:s,headers:ch()});}
async function gq(m,e){const k=e.GROQ_API_KEY;if(!k)return{error:'no_api_key'};for(const mo of GQ){try{const c=new AbortController;const t=setTimeout(()=>c.abort(),TM);const r=await fetch('https://api.groq.com/openai/v1/chat/completions',{method:'POST',headers:{'Authorization':'Bearer '+k,'Content-Type':'application/json'},body:JSON.stringify({model:mo,messages:m,temperature:0.7,max_tokens:MT}),signal:c.signal});clearTimeout(t);if(r.status===429)continue;if(!r.ok)continue;const d=await r.json();const c2=d?.choices?.[0]?.message?.content||'';if(c2)return{content:c2,model:'groq'};}catch{}}return{error:'provider_failed'};}
async function or(k,m,e){const en=M[k];if(!en?.id)return{error:'invalid_model'};const a=e.OPENROUTER_API_KEY;if(!a)return{error:'no_api_key'};try{const c=new AbortController;const t=setTimeout(()=>c.abort(),TM);const r=await fetch('https://openrouter.ai/api/v1/chat/completions',{method:'POST',headers:{'Authorization':'Bearer '+a,'Content-Type':'application/json'},body:JSON.stringify({model:en.id,messages:m,temperature:0.7,max_tokens:MT,reasoning:{enabled:false}}),signal:c.signal});clearTimeout(t);if(r.status===429)return{error:'rate_limit'};if(!r.ok)return{error:'provider_failed'};const d=await r.json();const ms=d?.choices?.[0]?.message;const c2=ms?.content||ms?.reasoning_content||'';if(c2)return{content:c2,model:k};return{error:'provider_failed'};}catch{return{error:'provider_failed'};}}
async function gqv(m,e){const k=e.GROQ_API_KEY;if(!k)return{error:'no_api_key'};for(const mo of GQV){try{const c=new AbortController;const t=setTimeout(()=>c.abort(),TM);const r=await fetch('https://api.groq.com/openai/v1/chat/completions',{method:'POST',headers:{'Authorization':'Bearer '+k,'Content-Type':'application/json'},body:JSON.stringify({model:mo,messages:m,temperature:0.7,max_tokens:4096}),signal:c.signal});clearTimeout(t);if(r.status===429)continue;if(!r.ok)continue;const d=await r.json();const c2=d?.choices?.[0]?.message?.content||'';if(c2)return{content:c2,model:'vision'};}catch{}}return{error:'provider_failed'};}
async function orv(m,e){const k=e.OPENROUTER_API_KEY;if(!k)return{error:'no_api_key'};for(const mo of ORV){try{const c=new AbortController;const t=setTimeout(()=>c.abort(),TM);const r=await fetch('https://openrouter.ai/api/v1/chat/completions',{method:'POST',headers:{'Authorization':'Bearer '+k,'Content-Type':'application/json'},body:JSON.stringify({model:mo,messages:m,temperature:0.7,max_tokens:4096,reasoning:{enabled:false}}),signal:c.signal});clearTimeout(t);if(r.status===429)continue;if(!r.ok)continue;const d=await r.json();const ms=d?.choices?.[0]?.message;const c2=ms?.content||ms?.reasoning_content||'';if(c2)return{content:c2,model:'vision'};}catch{}}return{error:'provider_failed'};}
export default{async fetch(r,e){if(r.method==='OPTIONS')return new Response(null,{headers:ch()});if(r.method!=='POST')return new Response('Method not allowed',{status:405});const a=r.headers.get('Authorization');if(!e.HOMA_WORKER_KEY||a!=='Bearer '+e.HOMA_WORKER_KEY)return jb({error:'unauthorized'},401);try{const b=await r.json();const m=b.messages;if(!Array.isArray(m)||!m.length)return jb({error:'messages required'});const l=b.language||'fa';const rm=b.model||'auto';const cm=!!b.codeMode;const ca=b.codeAction||'';const se=b.system_extra||'';const id=Array.isArray(b.image_data)?b.image_data.filter(x=>typeof x==='string'&&x.startsWith('data:image')):[];if(!M[rm])return jb({error:'invalid_model'});const s=sysP(l,cm,ca,se);if(id.length>0){const vm=[{role:'system',content:s+'\n\nشما تصاویر واقعی دریافت کرده‌اید. محتوای بصری هر تصویر را مستقیماً تحلیل کن.'}];for(const x of m){if(x.role==='user'&&x===m[m.length-1]){const c=[{type:'text',text:x.content||''}];for(const i of id.slice(0,2))c.push({type:'image_url',image_url:{url:i}});vm.push({role:'user',content:c});}else vm.push({role:x.role,content:x.content||''});}let res=await gqv(vm,e);if(res.error)res=await orv(vm,e);return jb(res);}const am=[{role:'system',content:s},...m];let res;if(rm==='auto'){res=await gq(am,e);if(res.error){const am2=pickAuto(m);res=await or(am2,am,e);}}else{res=await or(rm,am,e);if(res.error&&rm!=='lightning'){const rt=await or('lightning',am,e);if(!rt.error)res=rt;}}return jb(res);}catch(err){return jb({error:err.message||'internal_error'});}}};